scripts.dot_product:
def solve(inputs: dict) -> float:
    quantities = inputs['QUANTITIES']
    prices = inputs['PRICES']

    # Calculate dot product: sum of element-wise products
    total = sum(q * p for q, p in zip(quantities, prices))
    return float(total)

scripts.polynomial_eval:
def solve(inputs: dict) -> float:
    coeffs = inputs['COEFFS']
    x = inputs['X']

    # Evaluate polynomial using Horner's method for numerical stability
    # P(x) = c0 + c1*x + c2*x^2 + ... + cn*x^n
    result = 0
    for i, coeff in enumerate(coeffs):
        result += coeff * (x ** i)

    return float(result)

scripts.lcg:
def solve(inputs: dict) -> float:
    x = inputs['SEED']
    a = inputs['A']
    b = inputs['B']
    m = inputs['M']
    k = inputs['K']

    # Apply the LCG k times
    for _ in range(k):
        x = (a * x + b) % m

    return float(x)

